#!/usr/bin/env node
/**
 * Tests for hooks/lib/output-filter.js: the rewrite (through hooks/guard-shell.js, which returns it
 * as `allow` + `updatedInput`) and the filter itself (the same file run with `--filter <mode>`).
 * Zero dependencies — `node:test` on Node 18+.
 *
 *   node --test "tools/*.test.mjs"
 *
 * The rewrite cases are mostly refusals: the rewrite is auto-allowed, so anything chained, piped,
 * redirected or substituted must be left to the normal permission flow.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const HOOKS = join(dirname(fileURLToPath(import.meta.url)), '..', 'hooks');
const GUARD = join(HOOKS, 'guard-shell.js');
const FILTER = join(HOOKS, 'lib', 'output-filter.js');
const cwd = mkdtempSync(join(tmpdir(), 'filter-'));
process.on('exit', () => { try { rmSync(cwd, { recursive: true, force: true }); } catch { /* tmp */ } });

/** The guard's output for one command: null when it said nothing. */
function guard(command, tool_name = 'Bash', extra = {}) {
  const r = spawnSync(process.execPath, [GUARD], {
    input: JSON.stringify({ tool_name, tool_input: { command, ...extra }, cwd }), encoding: 'utf8',
  });
  assert.equal(r.status, 0);
  return r.stdout.trim() ? JSON.parse(r.stdout).hookSpecificOutput : null;
}

function filter(text, mode = 'test') {
  const r = spawnSync(process.execPath, [FILTER, '--filter', mode], { input: text, encoding: 'utf8' });
  return { out: r.stdout, status: r.status };
}

test('plain test and log commands are rewritten through the filter, allowed', () => {
  for (const [command, mode] of [
    ['dotnet test', 'test'],
    ['dotnet test --filter "FullyQualifiedName~Orders" -f net8.0', 'test'],
    ['npm test', 'test'],
    ['npm run test -- --run', 'test'],
    ['npx vitest run src/a.spec.ts', 'test'],
    ['docker compose logs api --since 10m', 'logs'],
    ['dotnet build', 'build'],
    ['dotnet build src/Orders.sln -c Release --no-restore', 'build'],
  ]) {
    const out = guard(command);
    assert.equal(out?.permissionDecision, 'allow', command);
    assert.equal(out.updatedInput.command,
      `set -o pipefail; ${command} 2>&1 | node "${FILTER.replace(/\\/g, '/')}" --filter ${mode}`, command);
  }
});

test('PowerShell records the command exit code before the pipe and exits with it', () => {
  const out = guard('dotnet test', 'PowerShell');
  assert.match(out.updatedInput.command, /^\$global:__rc = 0; & \{ dotnet test 2>&1; \$global:__rc = \$LASTEXITCODE \} \| node ".*output-filter\.js" --filter test; if \(\$global:__rc\) \{ exit \$global:__rc \}/);
  assert.doesNotMatch(out.updatedInput.command, /pipefail/);
});

// The rewritten PowerShell line, run for real against a `dotnet` shim that prints a short green log
// and exits with a chosen code: the filter alone would report 0, only the command knows it was 3.
const hasPwsh = spawnSync('pwsh', ['-NoProfile', '-Command', '$PSVersionTable.PSVersion.Major'], { encoding: 'utf8' }).status === 0;
const skipShim = !hasPwsh ? 'pwsh 7 not on PATH' : (process.platform === 'win32' ? false : 'the shim is a .cmd');

function runRewritten(shimExit) {
  const bin = mkdtempSync(join(tmpdir(), 'filter-bin-'));
  try {
    writeFileSync(join(bin, 'dotnet.cmd'), ['@echo off', 'echo Passed! - Failed: 0, Passed: 3, Total: 3', `exit /b ${shimExit}`, ''].join('\r\n'));
    const command = guard('dotnet test', 'PowerShell').updatedInput.command;
    const r = spawnSync('pwsh', ['-NoProfile', '-Command', command], {
      encoding: 'utf8', env: { ...process.env, PATH: `${bin};${process.env.PATH}` },
    });
    return { status: r.status, out: r.stdout };
  } finally {
    rmSync(bin, { recursive: true, force: true });
  }
}

test('PowerShell: a failing dotnet keeps its exit code through the filter, a passing one stays 0', { skip: skipShim }, () => {
  const red = runRewritten(3);
  assert.equal(red.status, 3, red.out);
  assert.match(red.out, /Passed!/);
  assert.equal(runRewritten(0).status, 0);
});

test('the rest of the tool input is preserved', () => {
  const out = guard('npm test', 'Bash', { description: 'Run tests', timeout: 600000 });
  assert.equal(out.updatedInput.description, 'Run tests');
  assert.equal(out.updatedInput.timeout, 600000);
});

test('never rewritten: opt-out, compound lines, help, listings, watch and follow', () => {
  for (const command of [
    'dotnet test # raw',
    'dotnet test #raw',
    'cd src && dotnet test',
    'dotnet test | tail -5',
    'dotnet test > out.txt',
    'dotnet test; echo done',
    'dotnet test $(cat args)',
    'dotnet test --list-tests',
    'dotnet test -t',
    'dotnet test --help',
    'npx vitest --watch',
    'npx vitest watch',
    'docker compose logs -f api',
    'docker compose logs --follow',
    'dotnet build # raw',
    'dotnet build --help',
    'dotnet build -v:diag',
    'dotnet build --verbosity detailed',
    'dotnet publish',
    'npm install',
  ]) {
    assert.equal(guard(command), null, command);
  }
});

test('a command that asks is not rewritten', () => {
  // Destructive check fires on the volume removal: ask wins, no allow, no rewrite.
  assert.equal(guard('docker compose down -v && dotnet test').permissionDecision, 'ask');
});

test('short output passes through untouched', () => {
  const text = 'Passed!  - Failed: 0, Passed: 3, Skipped: 0, Total: 3\n';
  const { out, status } = filter(text);
  assert.equal(out, text);
  assert.equal(status, 0);
});

test('long dotnet output keeps the failure block and the summary, exits 1', () => {
  const noise = Array.from({ length: 200 }, (_, i) => `  Restored project ${i} -> bin/Debug/net8.0/P${i}.dll`);
  const text = [
    ...noise.slice(0, 100),
    '  Failed Orders.Tests.Total_is_sum [12 ms]',
    '  Error Message:',
    '   Assert.Equal() Failure: Expected: 3, Actual: 4',
    '  Stack Trace:',
    '     at Orders.Tests.Total_is_sum() in C:\\src\\OrdersTests.cs:line 42',
    ...noise.slice(100),
    'Failed!  - Failed: 1, Passed: 41, Skipped: 0, Total: 42, Duration: 2 s',
  ].join('\n');
  const { out, status } = filter(text);
  assert.equal(status, 1);
  assert.match(out, /^\[output-filter\] \d+ of 206 lines/);
  assert.match(out, /Failed Orders\.Tests\.Total_is_sum/);
  assert.match(out, /Expected: 3, Actual: 4/);
  assert.match(out, /:line 42/);
  assert.match(out, /Failed!  - Failed: 1/);
  assert.match(out, /lines omitted/);
  assert.ok(out.split('\n').length < 60, 'most of the noise is gone');
});

test('long green run keeps the summary, exits 0', () => {
  const text = [
    ...Array.from({ length: 150 }, (_, i) => `  build step ${i}`),
    'Passed!  - Failed: 0, Passed: 42, Skipped: 0, Total: 42, Duration: 2 s',
  ].join('\n');
  const { out, status } = filter(text);
  assert.equal(status, 0);
  assert.match(out, /Passed!  - Failed: 0, Passed: 42/);
});

test('vitest summary with failures exits 1', () => {
  const text = [
    ...Array.from({ length: 80 }, (_, i) => ` ✓ src/ok${i}.spec.ts (3 tests) 4ms`),
    ' FAIL  src/cart.spec.ts > cart > totals',
    'AssertionError: expected 4 to be 3',
    ' Test Files  1 failed | 80 passed (81)',
    '      Tests  1 failed | 242 passed (243)',
  ].join('\n');
  const { out, status } = filter(text);
  assert.equal(status, 1);
  assert.match(out, /FAIL {2}src\/cart\.spec\.ts/);
  assert.match(out, /Tests {2}1 failed/);
  assert.doesNotMatch(out, /ok10\.spec/);
});

test('logs mode keeps errors with context and the tail, always exits 0', () => {
  const text = [
    ...Array.from({ length: 100 }, (_, i) => `api-1  | info: request ${i} 200`),
    'api-1  | fail: Microsoft.AspNetCore.Server[13] Unhandled exception',
    'api-1  |    at Orders.Api.Handler.Run() in /src/Handler.cs:line 7',
    ...Array.from({ length: 100 }, (_, i) => `api-1  | info: request ${100 + i} 200`),
  ].join('\n');
  const { out, status } = filter(text, 'logs');
  assert.equal(status, 0);
  assert.match(out, /Unhandled exception/);
  assert.match(out, /Handler\.cs:line 7/);
  assert.match(out, /request 199 200/);
  assert.doesNotMatch(out, /request 50 200/);
});

// A failing multi-target build as MSBuild prints it: the restore noise, each diagnostic once per target
// framework, then the same diagnostics listed again under "Build FAILED.".
const project = (tfm) => `[/src/Orders.Api/Orders.Api.csproj::TargetFramework=${tfm}]`;
const warning = (n, tfm) => `/src/Orders.Api/Services/Svc${n}.cs(${n},9): warning CS8618: Non-nullable property 'P${n}' must contain a non-null value when exiting constructor. ${project(tfm)}`;
const error = (tfm) => `/src/Orders.Api/Controllers/OrdersController.cs(42,17): error CS0103: The name 'total' does not exist in the current context ${project(tfm)}`;
const TFMS = ['net8.0', 'net9.0'];
const diagnostics = [1, 2, 3].flatMap((n) => TFMS.map((tfm) => warning(n, tfm))).concat(TFMS.map(error));
const restore = Array.from({ length: 80 }, (_, i) => `  Restored /src/Orders.Project${i}/Orders.Project${i}.csproj (in ${i + 100} ms).`);
const failedBuild = [
  'MSBuild version 17.8.3+195e7f5a3 for .NET',
  '  Determining projects to restore...',
  ...restore,
  ...diagnostics,
  '  Orders.Domain -> /src/Orders.Domain/bin/Debug/net8.0/Orders.Domain.dll',
  '',
  'Build FAILED.',
  '',
  ...diagnostics,
  '    6 Warning(s)',
  '    2 Error(s)',
  '',
  'Time Elapsed 00:00:12.34',
].join('\n');

test('a failing build keeps each distinct error and warning once with its count, and the summary; exits 1', () => {
  const { out, status } = filter(failedBuild, 'build');
  assert.equal(status, 1);
  assert.match(out, /^\[output-filter\] \d+ of \d+ lines/);
  const lines = out.split('\n');
  const count = (re) => lines.filter((l) => re.test(l)).length;
  assert.equal(count(/error CS0103/), 1, 'the error: once, not once per target framework and once more in the summary');
  assert.equal(count(/warning CS8618: .*'P1'/), 1);
  assert.equal(count(/warning CS8618/), 3, 'three distinct warnings');
  assert.match(out, /error CS0103.* \(x2\)$/m, 'seen under both target frameworks, not counted again in the re-listing');
  assert.match(out, /warning CS8618: .*'P3'.* \(x2\)$/m);
  for (const kept of [/^Build FAILED\./m, /^ {4}6 Warning\(s\)/m, /^ {4}2 Error\(s\)/m, /^Time Elapsed 00:00:12\.34/m]) {
    assert.match(out, kept);
  }
  assert.doesNotMatch(out, /Restored \/src/);
  assert.ok(lines.length < 25, 'most of the noise is gone');
});

test('a green build with warnings keeps the warnings once and the summary, exits 0', () => {
  const text = [
    ...restore,
    ...TFMS.map((tfm) => warning(1, tfm)),
    'Build succeeded.',
    '',
    ...TFMS.map((tfm) => warning(1, tfm)),
    '    2 Warning(s)',
    '    0 Error(s)',
    '',
    'Time Elapsed 00:00:03.10',
  ].join('\n');
  const { out, status } = filter(text, 'build');
  assert.equal(status, 0);
  assert.equal(out.split('\n').filter((l) => /warning CS8618/.test(l)).length, 1);
  assert.match(out, /^Build succeeded\./m);
  assert.match(out, /0 Error\(s\)/);
});

test('a build that never reaches a verdict keeps its tail, and an error in it still exits 1', () => {
  const text = [...restore, error('net8.0'), ...restore.slice(0, 20), 'Unhandled exception: out of memory'].join('\n');
  const { out, status } = filter(text, 'build');
  assert.equal(status, 1);
  assert.match(out, /error CS0103/);
  assert.match(out, /Unhandled exception: out of memory/);
});

test('a build whose output is short passes through untouched', () => {
  const text = 'Build succeeded.\n    0 Warning(s)\n    0 Error(s)\n\nTime Elapsed 00:00:01.20\n';
  const { out, status } = filter(text, 'build');
  assert.equal(out, text);
  assert.equal(status, 0);
});
